<script setup lang="ts">
import { Sparkles, ArrowUpRight, LoaderCircle, X, ImagePlus, Check, Save } from 'lucide-vue-next'
import { normalizePalette, type AiJob, type Asset, type ComponentData } from '@qinbian/shared'
const props=defineProps<{mode?:'component'|'palette';settings?:ComponentData;themeSetId?:string;targetType?:'resource'|'document';targetId?:string;targetRevision?:number;blockId?:string;sourceHtml?:string;beforeStart?:()=>Promise<void>}>()
const emit=defineEmits<{applied:[result:any]}>(),ctx=useQinbian()
const prompt=ref(''),model=ref('deepseek-v4-pro'),job=ref<AiJob|null>(null),busy=ref(false),applying=ref(false),showAssets=ref(false),selectedAssets=ref<Asset[]>([]),showBefore=ref(false)
const colorCount=ref(normalizePalette(props.settings?.palette,ctx.themes.value.find(t=>t.id===props.themeSetId)?.tokens).colors.length)
let timer:ReturnType<typeof setTimeout>|undefined
const running=computed(()=>!!job.value&&['queued','running','validating'].includes(job.value.status))
const stage=computed(()=>({queued:'正在准备素材与规范',running:'正在推敲这份版式',validating:'正在检查结构与样式',ready:'候选已完成，请预览确认',failed:'这次制作未完成',cancelled:'已取消制作',applied:'已应用候选'}[job.value?.status||'ready']))
onMounted(async()=>{try{const settings=await apiFetch<any>('/api/settings');model.value=settings.model}catch{}})
onBeforeUnmount(()=>clearTimeout(timer))
async function poll(){if(!job.value)return;try{job.value=await apiFetch<AiJob>(`/api/ai/jobs/${job.value.id}`);if(running.value)timer=setTimeout(poll,1200)}catch(e){ctx.error(e)}}
async function start(){if(!prompt.value.trim())return;busy.value=true;try{await props.beforeStart?.();await nextTick();job.value=await apiFetch<AiJob>('/api/ai/jobs',{method:'POST',body:{operation:props.mode==='palette'?'palette':props.sourceHtml?'edit':'generate',colorCount:colorCount.value,settings:props.settings,palette:props.settings?.palette,prompt:prompt.value,model:model.value,themeSetId:props.themeSetId||'shanhai',targetType:props.targetType,targetId:props.targetId,targetRevision:props.targetRevision,blockId:props.blockId,sourceHtml:props.sourceHtml,assetIds:selectedAssets.value.map(a=>a.id)}});colorCount.value=job.value.request.colorCount||colorCount.value;timer=setTimeout(poll,500)}catch(e){ctx.error(e)}finally{busy.value=false}}
async function cancel(){if(!job.value)return;try{job.value=await apiFetch(`/api/ai/jobs/${job.value.id}/cancel`,{method:'POST'})}catch(e){ctx.error(e)}}
async function apply(mode:'save'|'replace'|'insert'){if(!job.value)return;applying.value=true;try{const result=await apiFetch(`/api/ai/jobs/${job.value.id}/apply`,{method:'POST',body:{mode,revision:props.targetRevision,themeSetId:ctx.themes.value.find(t=>t.id===props.themeSetId&&!t.builtin)?.id||'mine'}});job.value={...job.value,status:'applied'};ctx.notify(mode==='save'?'候选已收进资源库':'候选已应用，原内容保留在历史版本中');emit('applied',result)}catch(e){ctx.error(e)}finally{applying.value=false}}
</script>
<template><section class="ai-panel"><div class="panel-title"><Sparkles :size="17"/><h3>{{mode==='palette'?'为主题取一组颜色':sourceHtml?'一起修改这枚组件':'让灵感成为版式'}}</h3></div><p class="muted small">描述具体的用途与变化。制作规范会随当前主题一同使用。</p><label class="sr-only" for="ai-prompt">AI制作要求</label><textarea id="ai-prompt" v-model="prompt" rows="5" placeholder="例如：做一枚读书分享会的邀请卡，留出时间、地点和报名说明，气质温润一些。" :disabled="running"/>
 <div class="ai-options"><select v-model="model" aria-label="AI模型" :disabled="running"><option value="deepseek-v4-pro">DeepSeek V4 Pro</option><option value="deepseek-flash">DeepSeek Flash</option></select><button class="icon-button" aria-label="为AI选择图片素材" title="选择参考图片素材" @click="showAssets=true"><ImagePlus :size="17"/></button></div>
 <label class="ai-color-count">配色数量<select v-model.number="colorCount" :disabled="running" aria-label="AI配色数量"><option v-for="n in [3,4,5,6]" :key="n" :value="n">{{n}} 色</option></select></label>
 <div v-if="selectedAssets.length" class="asset-chips"><button v-for="a in selectedAssets" :key="a.id" @click="selectedAssets=selectedAssets.filter(x=>x.id!==a.id)">{{a.name}} ×</button></div>
 <button v-if="!running" class="btn vermilion full" :disabled="busy||!prompt.trim()" @click="start"><Sparkles :size="15"/>{{busy?'正在准备…':job?.status==='failed'?'重新制作':mode==='palette'?'生成配色卡':sourceHtml?'生成修改候选':'生成组件'}}</button><button v-else class="btn full" @click="cancel"><X :size="15"/>取消本次制作</button>
 <div v-if="job" class="ai-progress" :class="job.status"><LoaderCircle v-if="running" :size="16" class="spin"/><Check v-else-if="job.status==='ready'||job.status==='applied'" :size="16"/><span>{{stage}}</span></div><p v-if="job?.error" class="error-message">{{job.error}}</p>
 <template v-if="job?.result"><div class="candidate-heading"><h4>{{job.result.name}}</h4><button v-if="sourceHtml" class="text-button" @click="showBefore=!showBefore">{{showBefore?'查看候选':'对照原组件'}}</button></div><div class="candidate-preview"><PaletteSwatches v-if="job.result.kind==='palette'" :palette="job.result.palette"/><HtmlPreview v-else :html="showBefore&&sourceHtml?sourceHtml:job.result.html" :max-height="480"/></div><p class="small muted">{{job.result.description}}</p><div v-if="job.status==='ready'" class="candidate-actions"><button class="btn full" :disabled="applying" @click="apply('save')"><Save :size="14"/>{{job.result.kind==='palette'?'收为配色卡':'另存为组件'}}</button><button v-if="targetId&&sourceHtml&&job.result.kind!=='palette'" class="btn primary full" :disabled="applying" @click="apply('replace')">确认替换选中组件</button><button v-else-if="targetId&&job.result.kind!=='palette'" class="btn primary full" :disabled="applying" @click="apply('insert')">加入当前编排</button></div></template>
 <p class="ai-note">仅发送制作要求、所选内容与必要规范。候选不会自动覆盖原稿。</p>
 <AssetPicker v-if="showAssets" @close="showAssets=false" @select="a=>{if(selectedAssets.length<8&&!selectedAssets.some(x=>x.id===a.id))selectedAssets.push(a);showAssets=false}"/>
</section></template>
